                <p className="text-gray-500 font-medium">{testimonials[active].type}</p>
              </div>
            </div>

            <div className="hidden md:flex flex-col gap-4">
              <button 
                onClick={prev}
                className="p-4 rounded-full bg-white shadow-md hover:bg-[#202c44] hover:text-white transition-all border border-gray-100"
              >
                <ChevronLeft />
              </button>
              <button 
                onClick={next}
                className="p-4 rounded-full bg-white shadow-md hover:bg-[#202c44] hover:text-white transition-all border border-gray-100"
              >
                <ChevronRight />
              </button>
            </div>
