import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Services from './components/Services';
import Benefits from './components/Benefits';
import About from './components/About';
import Team from './components/Team';
import Testimonials from './components/Testimonials';
import CTASection from './components/CTASection';
import ContactMap from './components/ContactMap';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState(window.location.hash || '#home');

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash || '#home';
      setCurrentPath(hash);

      // If navigating to a "page" (not an anchor in the current view), scroll to top
      if (hash === '#servicos' || hash === '#home') {
        window.scrollTo(0, 0);
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  // Determine if we are on the dedicated Services page
  const isServicesPage = currentPath.startsWith('#servicos');

  return (
    <div className="min-h-screen bg-white text-gray-900 selection:bg-[#202c44] selection:text-white">
      <Navbar currentPath={currentPath} />
      <main>
        {isServicesPage ? (
          <div className="pt-20">
            <Services />
            <CTASection />
          </div>
        ) : (
          <>
            <Hero />
            <Benefits />
            <About />
            <Team />
            <Testimonials />
            <CTASection />
            <ContactMap />
          </>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default App;

